```python
from __future__ import annotations
from abc import ABC, abstractmethod
import math

class Shape(ABC):
    """Abstract base class for geometric shapes."""

    @abstractmethod
    def area(self) -> float:
        """Return the area of the shape."""
        raise NotImplementedError


class Circle(Shape):
    """Circle defined by its radius."""

    def __init__(self, radius: float):
        if radius < 0:
            raise ValueError("Radius must be non‑negative")
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2

    def __repr__(self) -> str:
        return f"Circle(radius={self.radius})"


class Rectangle(Shape):
    """Rectangle defined by its width and height."""

    def __init__(self, width: float, height: float):
        if width < 0 or height < 0:
            raise ValueError("Width and height must be non‑negative")
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height

    def __repr__(self) -> str:
        return f"Rectangle(width={self.width}, height={self.height})"
```

**How it works**

- `Shape` inherits from `ABC` (Abstract Base Class) and declares an abstract method `area`. Any subclass must implement `area`, otherwise instantiation will raise a `TypeError`.
- `Circle` stores a radius, validates it, and computes the area with \(πr^2\).  
- `Rectangle` stores width and height, validates them, and computes the area with \(width × height\).  
- Both concrete classes provide a `__repr__` for readable debugging.

